echo "=== 1. Syntax check all Python files ===" && find "$TARGET_DIR" -name "*.py" | xargs -n 1 python3 -m py_compile && echo "Syntax: OK" && echo "" && echo "=== 2. Interface check ===" && python3 -c "import ast, os, sys; def params(p):
    tree = ast.parse(open(p).read());
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == 'run_agent':
            return [a.arg for a in node.args.args]
    return None
old = params(os.path.join(os.environ['ORIGINAL_DIR'], 'run_buggy.py'))
new = params(os.path.join(os.environ['TARGET_DIR'], 'run_buggy.py'))
assert new == old, f'run_agent parameters changed: {old} -> {new}'
print('run_agent interface: OK', new)" && echo "" && echo "=== 3. Diff summary ===" && diff -rq --exclude='*.pyc' --exclude='__pycache__' "$ORIGINAL_DIR" "$TARGET_DIR" 2>/dev/null | grep '^Files' || echo "(no file differences)" && echo "" && echo "=== All checks passed ==="

python3 -c "import os, re, sys; p=os.path.join(os.environ['TARGET_DIR'],'run_buggy.py'); txt=open(p).read().splitlines(); new=[]; inserted=False; for i,line in enumerate(txt):
    if 's/search_kwargs' in line:
        continue
    if line.strip().startswith('RETRIEVER_TOP_K'):
        continue
    new.append(line)
    if not inserted and (line.strip().startswith('from') or line.strip().startswith('import')):
        # if next line is not an import, insert constant after this line
        if i+1>=len(txt) or not (txt[i+1].strip().startswith('from') or txt[i+1].strip().startswith('import')):
            new.append('RETRIEVER_TOP_K = 5  # ENHANCED_PROGRAM_V1: increase retriever top‑k to capture multiple CSV rows')
            inserted=True
if not inserted:
    new.insert(0,'RETRIEVER_TOP_K = 5  # ENHANCED_PROGRAM_V1: increase retriever top‑k to capture multiple CSV rows')
# replace search_kwargs pattern
out='\n'.join([re.sub(r'search_kwargs={"k":\s*1}', 'search_kwargs={"k": RETRIEVER_TOP_K}  # ENHANCED_PROGRAM_V1: use higher k for better context', l) for l in new])+'\n'
open(p,'w').write(out); print('File updated')"

